corrected_code:
package notification

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	notifpb "myapp/gen/notification/v1"
	"myapp/auth"
	"myapp/mailer"
)

type NotificationServer struct {
	notifpb.UnimplementedNotificationServiceServer
	Mailer mailer.Mailer
}

func (s *NotificationServer) TriggerEmailVerification(ctx context.Context, req *notifpb.VerificationRequest) (*notifpb.VerificationResponse, error) {
	callerUser, ok := auth.UserFromContext(ctx)
	if !ok {
		return nil, status.Error(codes.Unauthenticated, "Authentication required")
	}

	if callerUser.ID != req.GetUserId() && !callerUser.IsAdmin {
		return nil, status.Error(codes.PermissionDenied, "Cannot request verification for other accounts")
	}

	err := s.Mailer.SendVerification(ctx, req.GetUserId())
	if err != nil {
		return nil, status.Errorf(codes.Internal, "Dispatch failed: %v", err)
	}

	return &notifpb.VerificationResponse{Success: true}, nil
}
